const params = $input.item.json;
const isOpenAI = params.apiProvider === 'openai';
const isJSON = params.mode === 'json';

let payload, url, headers;

if (isOpenAI) {
  payload = {
    model: params.model,
    messages: [],
    temperature: params.temperature,
    max_tokens: params.maxTokens
  };

  if (params.systemInstructions) {
    payload.messages.push({role: 'system', content: params.systemInstructions});
  }

  if (isJSON && !params.systemInstructions) {
    payload.messages.push({role: 'system', content: 'You must respond with valid JSON.'});
  }

  payload.messages.push({role: 'user', content: params.prompt});

  if (isJSON) {
    payload.response_format = {type: 'json_object'};
  }

  url = 'https://api.openai.com/v1/chat/completions';
  headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + '{{ $env.OPENAI_API_KEY }}'
  };

} else { // Anthropic
  payload = {
    model: params.model,
    messages: [{role: 'user', content: params.prompt}],
    temperature: params.temperature,
    max_tokens: params.maxTokens
  };

  if (params.systemInstructions) {
    payload.system = params.systemInstructions;
    if (isJSON) {
      payload.system += '\n\nYou must respond with valid JSON only.';
    }
  } else if (isJSON) {
    payload.system = 'You must respond with valid JSON only.';
  }

  url = 'https://api.anthropic.com/v1/messages';
  headers = {
    'Content-Type': 'application/json',
    'x-api-key': '{{ $env.ANTHROPIC_API_KEY }}',
    'anthropic-version': '2023-06-01'
  };
}

return {
  url,
  method: 'POST',
  headers,
  body: payload,
  originalParams: params
};

const response = $input.item.json.body || $input.item.json;
const params = $('Build API Request').item.json.originalParams;
const isOpenAI = params.apiProvider === 'openai';

let content, tokensUsed;

if (isOpenAI) {
  content = response.choices[0].message.content;
  tokensUsed = response.usage?.total_tokens || 0;
} else { // Anthropic
  content = response.content[0].text;
  const usage = response.usage || {};
  tokensUsed = (usage.input_tokens || 0) + (usage.output_tokens || 0);
}

return {
  content,
  tokensUsed,
  model: params.model,
  mode: params.mode,
  retryCount: params.retryCount
};

return {
  success: true,
  mode: 'text',
  outputText: $input.item.json.content,
  tokensUsed: $input.item.json.tokensUsed,
  model: $input.item.json.model
};

const content = $input.item.json.content;
const retryCount = $input.item.json.retryCount;

try {
  const parsed = JSON.parse(content);
  return {
    success: true,
    parseSuccess: true,
    mode: 'json',
    outputJson: parsed,
    tokensUsed: $input.item.json.tokensUsed,
    model: $input.item.json.model
  };
} catch (error) {
  return {
    success: false,
    parseSuccess: false,
    content,
    retryCount,
    originalParams: $('Build API Request').item.json.originalParams,
    parseError: error.message
  };
}

return {
  success: false,
  error: {
    type: 'ParseError',
    message: 'Failed to parse AI response as JSON after retry',
    details: {
      rawContent: $input.item.json.content,
      parseError: $input.item.json.parseError
    }
  }
};

const statusCode = $input.item.json.statusCode || 0;
const responseBody = $input.item.json.body || $input.item.json;

let errorType = 'APIError';
let message = 'AI API call failed';

if (statusCode === 429) {
  errorType = 'RateLimitError';
  message = 'Rate limit exceeded';
} else if (statusCode === 401 || statusCode === 403) {
  errorType = 'AuthError';
  message = 'Authentication failed - check API key';
} else if (statusCode >= 500) {
  errorType = 'ServerError';
  message = 'AI service error';
} else if (!statusCode) {
  errorType = 'NetworkError';
  message = 'Network error - unable to reach AI service';
}

return {
  success: false,
  error: {
    type: errorType,
    message: `${message} (${statusCode})`,
    details: {
      statusCode,
      responseBody
    }
  }
};
